import math
data=open('image.ppm').read().split()
W=int(data[1]); H=int(data[2])
px=list(map(int,data[4:]))
def pix(x,y):
    p=(y*W+x)*3; return px[p],px[p+1],px[p+2]
VW=2.6666667; VH=2.0
def ray(x,y):
    u=(x+0.5)/W; v=(y+0.5)/H
    return VW*(u-0.5),VH*(0.5-v),-1.0
samp=[]
for y in range(905,H,4):
    for x in list(range(0,400,3))+list(range(2000,W,3)):
        r,g,b=pix(x,y)
