def fit(Y0,s,sh):
    err=0
    for dx,dy,par in samp:
        wz=Y0/dy; wx=-dx*wz
        p=(math.floor((wx+sh)/s)+math.floor((wz+sh)/s))%2
        err+= (p!=par)
    return err
best=None
