#include <stdio.h>
#include <stdlib.h>
#include <math.h>
int main(){
  FILE*f=fopen("image.ppm","r");
  char m[8];int W,H,mx;fscanf(f,"%s %d %d %d",m,&W,&H,&mx);
  int N=W*H*3; int*px=malloc(sizeof(int)*N);
  for(int i=0;i<N;i++) fscanf(f,"%d",&px[i]);
  fclose(f);
  // collect clean floor samples (152/67), lower region
  double *U=malloc(sizeof(double)*2000000);double*V=malloc(sizeof(double)*2000000);int*PAR=malloc(sizeof(int)*2000000);int ns=0;
  for(int y=1100;y<H;y+=3)for(int x=0;x<W;x+=4){
    int p=(y*W+x)*3; int r=px[p],g=px[p+1],b=px[p+2];
    if(r==g&&g==b&&(r==152||r==67)){
      double u=(x+0.5)/W, v=(y+0.5)/H;
      U[ns]=u-0.5; V[ns]=0.5-v; PAR[ns]=(r==152)?0:1; ns++;
    }
  }
  printf("samples %d\n",ns);
  int best=1e9; double ba=0,bb=0,bY=0,bs=0;
  for(int ai=250;ai<=290;ai+=5)for(int bi=190;bi<=210;bi+=5){
    double ax=ai/100.0, ay=bi/100.0;
    for(int Yi=200;Yi<=600;Yi+=20){
      double Y0=Yi/1000.0;
      for(int si=40;si<=110;si+=5){
        double s=si/100.0, inv=1.0/s;
        int e=0;
        for(int i=0;i<ns;i++){
          double dy=ay*V[i], dx=ax*U[i];
          double wz=Y0/dy, wx=-dx*wz;
          int p=((int)floor(wx*inv)+(int)floor(wz*inv))%2;
          if(p!=PAR[i])e++;
        }
        if(e<best){best=e;ba=ax;bb=ay;bY=Y0;bs=s;}
      }
    }
  }
  printf("best err=%d (%.1f%%) ax=%.3f ay=%.3f Y0=%.3f s=%.3f\n",best,100.0*best/ns,ba,bb,bY,bs);
  return 0;
}
