#include <stdio.h>
#include <stdlib.h>
#include <math.h>
int main(){
  FILE*f=fopen("image.ppm","r");
  char m[8];int W,H,mx;if(fscanf(f,"%s %d %d %d",m,&W,&H,&mx)!=4)return 1;
  int N=W*H*3; int*px=malloc(sizeof(int)*N);
  for(int i=0;i<N;i++) if(fscanf(f,"%d",&px[i])!=1)return 1;
  fclose(f);
  double *U=malloc(sizeof(double)*2000000);double*V=malloc(sizeof(double)*2000000);int*PAR=malloc(sizeof(int)*2000000);int ns=0;
  for(int y=1100;y<H;y+=3)for(int x=0;x<W;x+=4){
    int p=(y*W+x)*3; int r=px[p];
    if(px[p]==px[p+1]&&px[p+1]==px[p+2]&&(r==152||r==67)){
      double u=(x+0.5)/W, v=(y+0.5)/H;
      U[ns]=u-0.5; V[ns]=0.5-v; PAR[ns]=(r==152)?0:1; ns++;
    }
  }
  printf("samples %d\n",ns);
  // Try BOTH parity conventions and also floor at +Y0 hitting plane y=-Y0 (dy>0 in our V because .5-v, but floor is BELOW so we need dy negative)
  // Actually floor below: ray goes to negative y. With V=0.5-v, at y>H/2 v>0.5 so V<0 => dy=ay*V<0. Good, dy<0 => wz=Y0/dy<0 (negative z, in front). wx=-dx*wz.
  int best=1e9; double ba=0,bb=0,bY=0,bs=0; int bp=0;
  for(int ai=200;ai<=360;ai+=10)for(int bi=150;bi<=260;ai+=10){
  for(int bi=150;bi<=260;bi+=10){
    double ax=ai/100.0, ay=bi/100.0;
    for(int Yi=200;Yi<=1000;Yi+=50){
      double Y0=Yi/1000.0;
      for(int si=25;si<=150;si+=5){
        double s=si/100.0, inv=1.0/s;
        for(int pc=0;pc<2;pc++){
        int e=0;
        for(int i=0;i<ns;i++){
          double dy=ay*V[i], dx=ax*U[i];
          double wz=Y0/dy, wx=-dx*wz;
          int p=((int)floor(wx*inv)+(int)floor(wz*inv))%2;
          if(p<0)p+=2;
          int want = pc? 1-PAR[i]:PAR[i];
          if(p!=want)e++;
        }
        if(e<best){best=e;ba=ax;bb=ay;bY=Y0;bs=s;bp=pc;}
        }
      }
    }
  }}
  printf("best err=%d (%.1f%%) ax=%.3f ay=%.3f Y0=%.3f s=%.3f pc=%d\n",best,100.0*best/ns,ba,bb,bY,bs,bp);
